Cypher query: MATCH (a:Article)-[:PUBLISHED_BY]->(p:Publisher),
      (a)-[:MENTIONS]->(g:Organization),
      (a)-[:MENTIONS]->(al:Organization)
WHERE (toLower(p.name) CONTAINS 'techcrunch' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'techcrunch'))
  AND (toLower(g.name) CONTAINS 'google' OR any(alias IN coalesce(g.aliases, []) WHERE toLower(alias) CONTAINS 'google'))
  AND (toLower(al.name) CONTAINS 'alphabet' OR any(alias IN coalesce(al.aliases, []) WHERE toLower(alias) CONTAINS 'alphabet'))
  AND (
    EXISTS {
      MATCH (a)-[:MENTIONS]->(law:Topic)
      WHERE any(term IN ['class action', 'antitrust', 'lawsuit'] WHERE toLower(law.name) CONTAINS term OR any(alias IN coalesce(law.aliases, []) WHERE toLower(alias) CONTAINS term))
    }
    OR EXISTS {
      MATCH (a)-[:MENTIONS]->(law:Event)
      WHERE any(term IN ['class action', 'antitrust', 'lawsuit'] WHERE toLower(law.name) CONTAINS term OR any(alias IN coalesce(law.aliases, []) WHERE toLower(alias) CONTAINS term))
    }
  )
OPTIONAL MATCH (g)-[r]-(connected)
RETURN DISTINCT a.name AS article, p.name AS publisher, g.name AS Google, type(r) AS connection, connected.name AS connected_to
LIMIT 10
