WHERE (
  (toLower(p.name) CONTAINS 'yardbarker' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'yardbarker'))
  AND (toLower(related.name) CONTAINS 'warriors' OR any(alias IN coalesce(related.aliases, []) WHERE toLower(alias) CONTAINS 'warriors'))
  AND EXISTS {
    MATCH (a)-[:MENTIONS]->(kuminga:__Entity__)
    WHERE toLower(kuminga.name) CONTAINS 'jonathan kuminga' OR any(alias IN coalesce(kuminga.aliases, []) WHERE toLower(alias) CONTAINS 'jonathan kuminga')
  }
  AND EXISTS {
    MATCH (a)-[:MENTIONS]->(moody:__Entity__)
    WHERE toLower(moody.name) CONTAINS 'moses moody' OR any(alias IN coalesce(moody.aliases, []) WHERE toLower(alias) CONTAINS 'moses moody')
  }
)
OR (
  (toLower(p.name) CONTAINS 'sporting news' OR any(alias IN coalesce(p.aliases, []) WHERE toLower(alias) CONTAINS 'sporting news'))
  AND (toLower(related.name) CONTAINS 'lakers' OR any(alias IN coalesce(related.aliases, []) WHERE toLower(alias) CONTAINS 'lakers'))
